using Contoso.Pricing;

namespace Contoso.Pricing.Tests;

[TestClass]
public sealed class PriceCalculatorTests
{
    private readonly PriceCalculator _calculator;

    public PriceCalculatorTests()
    {
        _calculator = new PriceCalculator();
    }

    // --- CalculateTotal: DataRow for inline scenarios ---

    [TestMethod]
    [DataRow(10.00, 1, 0.0, 10.00, DisplayName = "Single item, no tax")]
    [DataRow(10.00, 2, 0.0, 20.00, DisplayName = "Two items, no tax")]
    [DataRow(10.00, 1, 0.10, 11.00, DisplayName = "Single item, 10% tax")]
    [DataRow(25.50, 3, 0.08, 82.62, DisplayName = "Multiple items, 8% tax")]
    [DataRow(0.00, 5, 0.10, 0.00, DisplayName = "Zero price")]
    [DataRow(10.00, 0, 0.10, 0.00, DisplayName = "Zero quantity")]
    public void CalculateTotal_WithValidInputs_ReturnsExpected(
        double unitPrice, int quantity, double taxRate, double expected)
    {
        var result = _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate);

        Assert.AreEqual((decimal)expected, result);
    }

    // --- CalculateTotal: DynamicData with ValueTuples for boundary/edge cases ---

    [TestMethod]
    [DynamicData(nameof(CalculateTotalBoundaryData))]
    public void CalculateTotal_BoundaryCases_ReturnsExpected(
        decimal unitPrice, int quantity, decimal taxRate, decimal expected)
    {
        var result = _calculator.CalculateTotal(unitPrice, quantity, taxRate);

        Assert.AreEqual(expected, result);
    }

    public static IEnumerable<(decimal unitPrice, int quantity, decimal taxRate, decimal expected)>
        CalculateTotalBoundaryData =>
    [
        (0m, 0, 0m, 0m),
        (100m, 1, 0m, 100m),
        (100m, 1, 1m, 200m),       // max tax rate
        (0.01m, 1, 0m, 0.01m),     // smallest price
        (9999.99m, 100, 0.25m, 1_249_998.75m),
    ];

    // --- CalculateTotal: invalid inputs throw ---

    [TestMethod]
    [DataRow(-1.00, 1, 0.10, "unitPrice", DisplayName = "Negative price")]
    [DataRow(10.00, -1, 0.10, "quantity", DisplayName = "Negative quantity")]
    public void CalculateTotal_InvalidInputs_Throws(
        double unitPrice, int quantity, double taxRate, string expectedParam)
    {
        var ex = Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate));

        Assert.AreEqual(expectedParam, ex.ParamName);
    }

    [TestMethod]
    [DataRow(-0.01, DisplayName = "Tax rate below 0")]
    [DataRow(1.01, DisplayName = "Tax rate above 1")]
    public void CalculateTotal_InvalidTaxRate_Throws(double taxRate)
    {
        var ex = Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal(10m, 1, (decimal)taxRate));

        Assert.AreEqual("taxRate", ex.ParamName);
    }

    // --- ApplyDiscount: DynamicData with ValueTuples ---

    [TestMethod]
    [DynamicData(nameof(ApplyDiscountData))]
    public void ApplyDiscount_WithValidPercent_ReturnsExpected(
        decimal price, decimal discountPercent, decimal expected)
    {
        var result = _calculator.ApplyDiscount(price, discountPercent);

        Assert.AreEqual(expected, result);
    }

    public static IEnumerable<(decimal price, decimal discountPercent, decimal expected)>
        ApplyDiscountData =>
    [
        (100m, 0m, 100m),      // no discount
        (100m, 10m, 90m),      // 10%
        (100m, 50m, 50m),      // half off
        (100m, 100m, 0m),      // free
        (200m, 25m, 150m),     // 25% off 200
        (0m, 50m, 0m),         // zero price
        (49.99m, 15m, 42.4915m),
    ];

    // --- ApplyDiscount: invalid percent ---

    [TestMethod]
    [DataRow(-1.0, DisplayName = "Below 0%")]
    [DataRow(100.01, DisplayName = "Above 100%")]
    public void ApplyDiscount_InvalidPercent_Throws(double discountPercent)
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.ApplyDiscount(100m, (decimal)discountPercent));
    }

    // --- FormatPrice: DataRow ---

    [TestMethod]
    [DataRow(9.99, "$", "$9.99")]
    [DataRow(1234.5, "€", "€1234.50")]
    [DataRow(0.0, "$", "$0.00")]
    public void FormatPrice_WithSymbol_ReturnsFormatted(
        double price, string symbol, string expected)
    {
        var result = _calculator.FormatPrice((decimal)price, symbol);

        Assert.AreEqual(expected, result);
    }

    [TestMethod]
    public void FormatPrice_DefaultSymbol_UsesDollarSign()
    {
        var result = _calculator.FormatPrice(5.00m);

        Assert.StartsWith("$", result);
        Assert.AreEqual("$5.00", result);
    }
}

